const alliances={t:'setups',title:'European alliances before 1914',head:'System',cols:['Principal members'],rows:[['Triple Alliance','Germany, Austria-Hungary, Italy'],['Triple Entente','France, Russia, Britain'],['Flashpoint','Balkans: Serbia, Bosnia, Austria-Hungary'],['Italy in 1914','Stayed neutral, joined the Entente in 1915']]};
