const compare={t:'setups',title:'Total war compared',head:'Feature',cols:['World War I','World War II'],rows:[['Main style','Trench stalemate then late mobility','Mobile armour and air power'],['Fronts','Europe, Middle East, colonies','Europe, Africa, Asia, Pacific'],['Home front','Rationing, propaganda, women workers','Larger mobilization and bombing'],['Ending','Armistice, 11 Nov 1918','Surrenders in 1945']]};
const atrocities={t:'setups',title:'Mass atrocities: approximate scholarly figures',head:'Event',cols:['Years / place','Approximate deaths'],rows:[['Armenian genocide','1915–16, Ottoman lands','Several hundred thousand to over 1 million'],['Holocaust','1933–45, Nazi-controlled Europe','About 6 million Jews; others also murdered'],['Holodomor','1932–33, Soviet Ukraine','Millions; estimates vary'],['Cambodian genocide','1975–79, Cambodia','About 1.5–2 million'],['Rwandan genocide','1994, Rwanda','About 500,000–800,000 or more']]};
const TRY=[
 ['A fictional pilot’s diary from 1916 describes tanks crossing a trench line for the first time. Which feature of the war does this illustrate?','technological change in warfare',['the end of industrial production','a negotiated peace in 1914'],'Match the machine in the source to the broader process of change on the battlefield.',board('Fictional diary',['Source describes tanks on the Western Front','Tanks were new in 1916','Decide what larger change they show'])],
 ['A fictional leader in 1936 rebuilds forces in a demilitarized border zone and meets only protests. Which pattern fits the 1930s?','aggression met by weak collective response',['strict enforcement of the Versailles limits','immediate world war'],'Compare what the leader did with what other states did in response.',flow('Fictional border crisis',['Challenge','Protests','Next step'],['Treaty limit broken','No firm response','Aggression continues'])],
 ['A fictional student says World War II began only because of one treaty. Which revision is best supported?','several connected causes, including economic crisis and aggression, should be weighed',['treaties never affect later politics','the treaty should be left out of any explanation'],'A strong causal argument weighs more than one factor and tests each.',board('Fictional claim',['Claim: one treaty explains everything','Test: what else changed by 1939?','Revise to a multi-cause argument'])]
];
const check=i=>{const [q,right,wrong,hint,pic]=TRY[i],c=choose(right,wrong,i);return {prompt:`Try it: ${q[0].toLowerCase()+q.slice(1)} ${c.text}. Answer A, B or C.`,answer:c.letter,options:['A','B','C'],hint,pic};};
